import{_ as o,a0 as r,w as i,s as d,I as t,x as s,a1 as p,A as l,ao as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"如何從 KDE Plasma 5.23 升級到 5.24 | LCTT x X-CMD","titleTemplate":false,"description":"如何從 KDE Plasma 5.23 升級到 5.24 | LCTT (202202) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何從 KDE Plasma 5.23 升級到 5.24 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何從 KDE Plasma 5.23 升級到 5.24 | LCTT (202202) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202202/20220208 How to Upgrade to KDE Plasma 5.24 from 5.23","title":"如何從 KDE Plasma 5.23 升級到 5.24","tag":"202202","desc":""},"relativePath":"202202/20220208 How to Upgrade to KDE Plasma 5.24 from 5.23.md","filePath":"[post].md"}'),u={name:"202202/20220208 How to Upgrade to KDE Plasma 5.24 from 5.23.md"};function m(b,a,g,f,k,P){const e=r("Link");return i(),d("div",null,[a[25]||(a[25]=t("h1",{id:"如何從-kde-plasma-5-23-升級到-5-24",tabindex:"-1"},[s("如何從 KDE Plasma 5.23 升級到 5.24 "),t("a",{class:"header-anchor",href:"#如何從-kde-plasma-5-23-升級到-5-24","aria-label":"Permalink to “如何從 KDE Plasma 5.23 升級到 5.24”"},"​")],-1)),a[26]||(a[26]=t("blockquote",null,[t("p",null,"KDE 團隊宣佈了 KDE Plasma 5.24 LTS 版，已經可以下載和安裝了。如果你打算從以前的版本升級，在這裏我們給你提供了從 5.23 升級到 5.24 的簡明步驟。")],-1)),a[27]||(a[27]=t("p",null,[t("img",{src:"https://www.debugpoint.com/wp-content/uploads/2022/02/KDE-Plasma-5.4-Desktop-1024x576.jpg",alt:"KDE Plasma 5.24 桌面"})],-1)),a[28]||(a[28]=t("p",null,"KDE Plasma 5.24 是 Plasma 桌面的第 26 個版本，帶來了顯著的視覺改變和一些後端性能的提升。在這個版本中，你會看到全新的牆紙、Breeze 主題的視覺變化、指紋登錄和一個全新的概覽屏幕等等。",-1)),t("p",null,[a[1]||(a[1]=s("你可以在我們的綜述文章裏閲讀有關 ",-1)),p(e,{href:"https://www.debugpoint.com/2022/01/kde-plasma-5-24/"},{default:l(()=>[...a[0]||(a[0]=[s("KDE Plasma 5.24 功能的細節",-1)])]),_:1}),a[2]||(a[2]=s("。",-1))]),a[29]||(a[29]=n(`<p>如果你正在運行 KDE Plasma 的早期版本，你可以按本文説明升級到最新版本。</p><h3 id="如何升級到-kde-plasma-5-24" tabindex="-1">如何升級到 KDE Plasma 5.24 <a class="header-anchor" href="#如何升級到-kde-plasma-5-24" aria-label="Permalink to “如何升級到 KDE Plasma 5.24”">​</a></h3><p>這個版本的升級包大小適中，在我的測試機器上大約是 450MB 以上。在開始升級過程之前，請確保關閉所有應用程序並保存你的數據。</p><p>一般來説，KDE 的升級是非常穩定的，它從來不會失敗。但是，如果你想格外謹慎，並且有寶貴的數據，你可能想對這些進行備份。但同樣，在我看來，我相信這是沒有必要的。</p><h4 id="步驟" tabindex="-1">步驟 <a class="header-anchor" href="#步驟" aria-label="Permalink to “步驟”">​</a></h4><p>如果你是在 KDE Neon 之中、滾動發佈的發行版（如 Arch Linux、Manjaro 之類）中運行 KDE Plasma 5.23，你可以打開 KDE 工具 “<ruby>發現<rt>Discover</rt></ruby>”，點擊檢查更新。</p><p>你可以通過“<ruby>發現<rt>Discover</rt></ruby>”的升級包列表驗證 Plasma 5.24 是否可用。</p><p>一旦確認可用，點擊“<ruby>發現<rt>Discover</rt></ruby>”窗口右上方的“<ruby>全部更新<rt>Update All</rt></ruby>”按鈕。</p><p>另外，你也可以從終端運行下面的命令，在 KDE Neon 中開始升級過程。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt update</span></span>
<span class="line"><span>sudo pkcon update</span></span></code></pre></div><p>升級過程完成後重啓系統。</p><p>而重啓後，你應該看到全新的 KDE Plasma 5.24 出現在你面前。</p><h3 id="在-fedora-35-和-ubuntu-21-10-中升級-kde-plasma-5-24" tabindex="-1">在 Fedora 35 和 Ubuntu 21.10 中升級 KDE Plasma 5.24 <a class="header-anchor" href="#在-fedora-35-和-ubuntu-21-10-中升級-kde-plasma-5-24" aria-label="Permalink to “在 Fedora 35 和 Ubuntu 21.10 中升級 KDE Plasma 5.24”">​</a></h3>`,13)),t("p",null,[a[6]||(a[6]=s("截至目前，",-1)),p(e,{href:"https://www.debugpoint.com/2021/09/fedora-35/"},{default:l(()=>[...a[3]||(a[3]=[s("Fedora 35",-1)])]),_:1}),a[7]||(a[7]=s(" 和 ",-1)),p(e,{href:"https://www.debugpoint.com/2021/07/ubuntu-21-10/"},{default:l(()=>[...a[4]||(a[4]=[s("Ubuntu 21.10",-1)])]),_:1}),a[8]||(a[8]=s(" 是兩個主要的 KDE 的發行版。由於 ",-1)),p(e,{href:"https://docs.fedoraproject.org/en-US/fesco/Updates_Policy/#stable-releases"},{default:l(()=>[...a[5]||(a[5]=[s("更新政策",-1)])]),_:1}),a[9]||(a[9]=s("，Fedora 35 不會得到這個版本，而 Fedora 36 也將很快發佈。",-1))]),a[30]||(a[30]=n(`<p>然而，如果你仍然想做實驗，你可以在 Ubuntu 21.10 和 Ubuntu 21.04 中使用下面的 Backports PPA 安裝這個新版本的 Plasma 桌面。在這樣做的時候，請確保你保留一份數據備份。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo add-apt-repository ppa:kubuntu-ppa/backports</span></span>
<span class="line"><span>sudo apt-get full-upgrade</span></span></code></pre></div><p>在 Fedora 35 中，我試圖通過下面的 COPR 倉庫來安裝。但是有太多的依賴性衝突需要解決，在一個穩定的系統中嘗試這樣做是有風險的。我建議目前不要在 Fedora 35 中嘗試下面的方法。當然你仍然可以通過 <code>allowerasing</code> 標誌來安裝。但不要這樣做。</p><p>另外，我猜 Fedora 35 的官方版本會在第一個小版本（即 5.24.1）發佈時更新，該版本將於 2022 年 2 月 15 日發佈，所以你可以等到那時。</p><p>另外，等待 Fedora 36 也是比較明智的做法，因為它將這個版本作為默認版本。Fedora 36 將於 2022 年 4 月發佈。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/02/Trying-to-Install-Plasma-5.24-in-Fedora-35-1024x576.jpg" alt="試圖在 Fedora 35 中安裝 Plasma 5.24"></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf copr enable marcdeop/plasma</span></span>
<span class="line"><span>sudo dnf copr enable marcdeop/kf5</span></span>
<span class="line"><span>sudo dnf upgrade --refresh</span></span></code></pre></div><h3 id="升級後的反饋" tabindex="-1">升級後的反饋 <a class="header-anchor" href="#升級後的反饋" aria-label="Permalink to “升級後的反饋”">​</a></h3><p>我在虛擬機中運行了升級過程，並安裝了新的 KDE Plasma 5.23。升級過程很順利，沒有出現意外或錯誤。好吧，到目前為止，它對我來説從未失敗過。</p><p>升級時間完全取決於你的互聯網連接和 KDE 服務器。一般來説，它應該在 30 分鐘內完成。</p><p>升級過程後的第一次重啓很順利，沒有花費多少時間。</p><p>從性能上講，我覺得它比之前的版本更流暢，這要歸功於幾個錯誤的修復和底層的性能優化。</p><p>所以，總的來説，如果你在使用 KDE Neon，你可以安全地升級。否則就等待 Ubuntu 和 Fedora 穩定版的軟件包。</p><p>享受全新的 KDE Plasma 吧！</p><hr>`,15)),t("p",null,[a[11]||(a[11]=s("via: ",-1)),p(e,{href:"https://www.debugpoint.com/2022/02/upgrade-kde-plasma-5-24/"},{default:l(()=>[...a[10]||(a[10]=[s("https://www.debugpoint.com/2022/02/upgrade-kde-plasma-5-24/",-1)])]),_:1})]),t("p",null,[a[16]||(a[16]=s("作者：",-1)),p(e,{href:"https://www.debugpoint.com/author/admin1/"},{default:l(()=>[...a[12]||(a[12]=[s("Arindam",-1)])]),_:1}),a[17]||(a[17]=s(" 選題：",-1)),p(e,{href:"https://github.com/lujun9972"},{default:l(()=>[...a[13]||(a[13]=[s("lujun9972",-1)])]),_:1}),a[18]||(a[18]=s(" 譯者：",-1)),p(e,{href:"https://github.com/wxy"},{default:l(()=>[...a[14]||(a[14]=[s("wxy",-1)])]),_:1}),a[19]||(a[19]=s(" 校對：",-1)),p(e,{href:"https://github.com/wxy"},{default:l(()=>[...a[15]||(a[15]=[s("wxy",-1)])]),_:1})]),t("p",null,[a[22]||(a[22]=s("本文由 ",-1)),p(e,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...a[20]||(a[20]=[s("LCTT",-1)])]),_:1}),a[23]||(a[23]=s(" 原創編譯，",-1)),p(e,{href:"https://linux.cn/"},{default:l(()=>[...a[21]||(a[21]=[s("Linux中國",-1)])]),_:1}),a[24]||(a[24]=s(" 榮譽推出",-1))])])}const E=o(u,[["render",m]]);export{w as __pageData,E as default};
